class Traitur {
  constructor(name) {
    this.name = name;
    this.entries = [];
  }

  async createEntry(title, content) {
    const entry = {title, content, timestamp: Date.now()};
    this.entries.push(entry);
    return entry;
  }

  async getCompleteEntry(id) {
    return this.entries.find(e => e.id === id);
  }
  // probably need to expose some id generator
}

